27	// engineCtr returns a network-attached container (built the way production
28	// builds it) after reading the given bridge outcome.
29	func engineCtr(t *testing.T, b pathBridge) pathContainer {
30		t.Helper()
31		return bridgeCtr(t, "app_net", true).withBridgeRead(b)
32	}
33	
34	func TestPathContainerWithBridgeRead(t *testing.T) {
35		attached := bridgeCtr(t, "app_net", true)
36		tests := []struct {
37			name       string
38			ctr        pathContainer
39			in         pathBridge
40			wantBridge string
41			wantEngine engineView
42		}{
43			{"found sets the bridge", attached, pathBridge{State: bridgeFound, Name: "docker0"}, "docker0", engineNone},
44			{"found, user-defined bridge", attached, pathBridge{State: bridgeFound, Name: "br-3f2a1b4c5d6e"}, "br-3f2a1b4c5d6e", engineNone},
45			{"absent hides the engine", attached, pathBridge{State: bridgeAbsent}, "", engineHidden},
46			{"unverified", attached, pathBridge{State: bridgeUnverified}, "", engineUnverified},
47			{"not read changes nothing", attached, pathBridge{State: bridgeNotRead}, "", engineNone},
48			{"host mode", bridgeCtr(t, "host", true), pathBridge{State: bridgeAbsent}, "", engineNone},
49			{"none mode", bridgeCtr(t, "none", true), pathBridge{State: bridgeUnverified}, "", engineNone},
50			{"shared namespace", bridgeCtr(t, "container:abc", true), pathBridge{State: bridgeAbsent}, "", engineNone},
51			{"stopped (undetermined)", bridgeCtr(t, "app_net", false), pathBridge{State: bridgeAbsent}, "", engineNone},
52			{"host mode, found", bridgeCtr(t, "host", true), pathBridge{State: bridgeFound, Name: "docker0"}, "", engineNone},
53		}
54		for _, tt := range tests {
55			t.Run(tt.name, func(t *testing.T) {
56				before := tt.ctr
57				got := tt.ctr.withBridgeRead(tt.in)
58	
59				if got.Bridge != tt.wantBridge || got.Engine != tt.wantEngine {
60					t.Errorf("Bridge, Engine = %q, %v; want %q, %v", got.Bridge, got.Engine, tt.wantBridge, tt.wantEngine)
61				}
62				// Everything else is carried over unchanged.
63				wantRest := before
64				wantRest.Bridge, wantRest.Engine = tt.wantBridge, tt.wantEngine
65				if got != wantRest {
66					t.Errorf("withBridgeRead changed more than Bridge/Engine: got %+v, want %+v", got, wantRest)
67				}
68				// The receiver is not modified.
69				if tt.ctr != before {
70					t.Errorf("withBridgeRead modified its receiver: %+v, was %+v", tt.ctr, before)
71				}
72			})
73		}
74	}
