76	// Two calls from the same receiver do not leak into each other.
77	func TestPathContainerWithBridgeReadReturnsACopy(t *testing.T) {
78		base := bridgeCtr(t, "app_net", true)
79		a := base.withBridgeRead(pathBridge{State: bridgeFound, Name: "docker0"})
80		b := base.withBridgeRead(pathBridge{State: bridgeAbsent})
81		c := base.withBridgeRead(pathBridge{State: bridgeUnverified})
82	
83		if base.Bridge != "" || base.Engine != engineNone {
84			t.Errorf("receiver = Bridge %q, Engine %v; want untouched", base.Bridge, base.Engine)
85		}
86		if a.Bridge != "docker0" || a.Engine != engineNone {
87			t.Errorf("found copy = %q, %v", a.Bridge, a.Engine)
88		}
89		if b.Bridge != "" || b.Engine != engineHidden {
90			t.Errorf("absent copy = %q, %v", b.Bridge, b.Engine)
91		}
92		if c.Bridge != "" || c.Engine != engineUnverified {
93			t.Errorf("unverified copy = %q, %v", c.Bridge, c.Engine)
94		}
95	}
