97	func TestPathStepsEngineOrder(t *testing.T) {
98		hidden := engineCtr(t, pathBridge{State: bridgeAbsent})
99		unverified := engineCtr(t, pathBridge{State: bridgeUnverified})
100		found := engineCtr(t, pathBridge{State: bridgeFound, Name: "docker0"})
101		plain := bridgeCtr(t, "app_net", true)
102		host := bridgeCtr(t, "host", true).withBridgeRead(pathBridge{State: bridgeAbsent})
103		hops := []nettrace.Hop{stepsHop1}
104	
105		withEngine := []pathStepKind{stepContainer, stepNetwork, stepEngine, stepSource, stepInterface, stepGateway, stepTrace, stepHop}
106		withBridge := []pathStepKind{stepContainer, stepNetwork, stepBridge, stepSource, stepInterface, stepGateway, stepTrace, stepHop}
107		neither := []pathStepKind{stepContainer, stepNetwork, stepSource, stepInterface, stepGateway, stepTrace, stepHop}
108	
109		tests := []struct {
110			name  string
111			ctr   pathContainer
112			route *pathRoute
113			hops  []nettrace.Hop
114			want  []pathStepKind
115		}{
116			{"engine hidden", hidden, stepsRoute, hops, withEngine},
117			{"engine unverified", unverified, stepsRoute, hops, withEngine},
118			{"engine, no route, no hop", hidden,
119				nil, nil, []pathStepKind{stepContainer, stepNetwork, stepEngine, stepSource, stepTrace}},
120			{"engine, hop before route", hidden,
121				nil, hops, []pathStepKind{stepContainer, stepNetwork, stepEngine, stepSource, stepTrace, stepHop}},
122			{"bridge found: bridge row, no engine row", found, stepsRoute, hops, withBridge},
123			{"neither bridge nor engine: order unchanged", plain, stepsRoute, hops, neither},
124			{"host mode: nothing", host, stepsRoute, hops, neither},
125		}
126		for _, tt := range tests {
127			t.Run(tt.name, func(t *testing.T) {
128				ctr := tt.ctr
129				before := ctr
130				got := pathSteps(&ctr, tt.route, tt.hops)
131				if kinds := stepKinds(got); !slices.Equal(kinds, tt.want) {
132					t.Fatalf("kinds = %v, want %v", kinds, tt.want)
133				}
134				// Never a bridge row and an engine row together.
135				var nBridge, nEngine int
136				for _, s := range got {
137					switch s.Kind {
138					case stepBridge:
139						nBridge++
140					case stepEngine:
141						nEngine++
142					}
143				}
144				if nBridge+nEngine > 1 {
145					t.Errorf("%d bridge and %d engine rows, want at most one in total", nBridge, nEngine)
146				}
147				if ctr != before {
148					t.Errorf("pathSteps modified its container input")
149				}
150			})
151		}
152	}
153	
154	// A this-machine source (no container) never shows an engine row.
155	func TestPathStepsEngineAbsentWithoutContainer(t *testing.T) {
156		for _, s := range pathSteps(nil, stepsRoute, []nettrace.Hop{stepsHop1}) {
157			if s.Kind == stepEngine {
