195						t.Errorf("cell %q carries an escape sequence (Rule 122)", c)
196					}
197				}
198				// 47 cells at most, so nothing is truncated at 80 columns.
199				if w := ansi.StringWidth(got.address); w > engineAddressMaxCols {
200					t.Errorf("address is %d cells wide, want at most %d", w, engineAddressMaxCols)
