230			{"no bridge, no engine: unchanged", bridgeCtr(t, "app_net", true), traceNoEngineText},
231			{"host mode: unchanged", bridgeCtr(t, "host", true), textTraceSharedHost},
232		}
233		for _, tt := range tests {
