236				if got := step.addressCell(); got != tt.want {
237					t.Errorf("trace address = %q, want %q", got, tt.want)
238				}
239				if got := cellsOf(step); got.step != "trace" || got.hop != "" || got.rtt != "" {
240					t.Errorf("trace cells = %+v", got)
241				}
242			})
243		}
