246	// Neither the engine row nor the trace row (with an engine row present) names
247	// an IP address or a bridge: the whole point is that the location is unknown.
248	func TestPathEngineTextsLeakNothing(t *testing.T) {
249		for _, state := range []bridgeState{bridgeAbsent, bridgeUnverified} {
