251			for _, kind := range []pathStepKind{stepEngine, stepTrace} {
252				text := pathStep{Kind: kind, Container: ctr}.addressCell()
253				for _, word := range strings.Fields(text) {
254					word = strings.Trim(word, "(),.:;")
255					if _, err := netip.ParseAddr(word); err == nil {
256						t.Errorf("state %v kind %v: %q contains the address %q", state, kind, text, word)
257					}
258				}
259				lower := strings.ToLower(text)
260				for _, bad := range []string{"docker0", "br-", ctr.Addr.String(), ctr.Gateway.String()} {
261					if strings.Contains(lower, bad) {
