1	package netdiag
2	
3	import (
4		"fmt"
5		"net/netip"
6		"strings"
7	
8		"github.com/anthnel/devdesk/internal/docker"
9	)
10	
11	// containerAttach says how a container is attached to a network.
12	type containerAttach int
13	
14	// The ways a container can be attached.
15	const (
16		attachNetwork containerAttach = iota
17		attachHost
18		attachNone
19		attachShared
20		attachUndetermined
21	)
22	
23	// pathContainer is what the column says about the container a trace starts in.
24	type pathContainer struct {
25		Name     string // display-safe
26		Known    bool   // false: the inspection failed
27		Running  bool
28		Attach   containerAttach
29		Network  string     // attachNetwork only, display-safe
30		Networks int        // number of endpoints, for "undetermined (N networks)"
31		Addr     netip.Addr // the container's IPv4 on Network
32		Gateway  netip.Addr // Network's gateway
33		Bridge   string     // attachNetwork only: the host interface read for Network; "" when none
34	}
35	
36	// withBridge returns a copy of c carrying the bridge interface name. The name
37	// is kept only for a container attached to a network, and only when not empty.
38	func (c pathContainer) withBridge(name string) pathContainer {
39		if c.Attach == attachNetwork && name != "" {
40			c.Bridge = name
41		}
42		return c
43	}
44	
45	const (
46		modeHost            = "host"
47		modeNone            = "none"
48		modeSharedPrefix    = "container:"
49		textUndetermined    = "undetermined"
50		textHostNetwork     = "host (shares this machine's stack)"
51		textNoNetwork       = "none (no network)"
52		textSharedNetwork   = "shares another container's network"
53		textNotRunning      = "not running"
54		textTraceFromHost   = "from this machine, not from the container"
55		textTraceSharedHost = "from this machine (shared with the container)"
56	)
57	
58	// newPathContainer converts an inspection into a pathContainer. Every text the
59	// engine returned is sanitized here, so the cells are display-safe.
60	func newPathContainer(src pathSource, n docker.ContainerNetworking, err error) pathContainer {
61		c := pathContainer{Name: src.Name, Attach: attachUndetermined}
62		if err != nil {
63			return c
64		}
65		c.Known = true
66		if name := engineText(n.Name); name != "" {
67			c.Name = name
68		}
69		c.Running = n.Running
70		if !n.Running {
71			return c
72		}
73		switch {
74		case n.Mode == modeHost:
75			c.Attach = attachHost
76		case n.Mode == modeNone:
77			c.Attach = attachNone
78		case strings.HasPrefix(n.Mode, modeSharedPrefix):
79			c.Attach = attachShared
80		default:
81			c.Networks = len(n.Networks)
82			if picked, ok := routeEndpoint(n); ok {
83				c.Attach = attachNetwork
84				c.Network = engineText(picked.Name)
85				c.Addr = picked.IPv4
86				c.Gateway = picked.Gateway
87			}
88		}
89		return c
90	}
91	
92	// routeEndpoint returns the endpoint holding the container's default route.
93	// It reports false for host, none and shared-namespace modes, and when the
94	// route cannot be told (see defaultRouteNetwork).
95	func routeEndpoint(n docker.ContainerNetworking) (docker.EndpointNetwork, bool) {
96		if n.Mode == modeHost || n.Mode == modeNone || strings.HasPrefix(n.Mode, modeSharedPrefix) {
97			return docker.EndpointNetwork{}, false
98		}
99		return defaultRouteNetwork(n.Networks)
100	}
101	
102	// defaultRouteNetwork picks the network that holds the container's default
103	// route: among the endpoints with a gateway, the one with the strictly highest
104	// gateway priority. A tie, or a priority missing among several candidates, is
105	// never guessed. The input is not modified.
106	func defaultRouteNetwork(nets []docker.EndpointNetwork) (docker.EndpointNetwork, bool) {
107		var candidates []docker.EndpointNetwork
108		for _, e := range nets {
109			if e.Gateway.IsValid() {
110				candidates = append(candidates, e)
111			}
112		}
113		switch len(candidates) {
114		case 0:
115			return docker.EndpointNetwork{}, false
116		case 1:
117			return candidates[0], true
118		}
119		best := -1
120		for i, e := range candidates {
121			if e.GwPriority == nil {
122				return docker.EndpointNetwork{}, false
123			}
124			if best < 0 || *e.GwPriority > *candidates[best].GwPriority {
125				best = i
126			}
127		}
128		for i, e := range candidates {
129			if i != best && *e.GwPriority == *candidates[best].GwPriority {
130				return docker.EndpointNetwork{}, false
131			}
132		}
133		return candidates[best], true
134	}
135	
136	// containerText is the Address cell of the container row.
137	func (c pathContainer) containerText() string {
138		switch {
139		case c.Known && !c.Running:
140			return c.Name + " (" + textNotRunning + ")"
141		case c.Attach == attachNetwork && c.Addr.IsValid():
142			return c.Name + " (" + c.Addr.String() + ")"
143		}
144		return c.Name
145	}
146	
147	// networkText is the Address cell of the network row.
148	func (c pathContainer) networkText() string {
149		switch c.Attach {
150		case attachNetwork:
151			if c.Gateway.IsValid() {
152				return c.Network + " via " + c.Gateway.String()
153			}
154			return c.Network
155		case attachHost:
156			return textHostNetwork
157		case attachNone:
158			return textNoNetwork
159		case attachShared:
160			return textSharedNetwork
161		}
162		if c.Networks > 1 {
163			return fmt.Sprintf("%s (%d networks)", textUndetermined, c.Networks)
164		}
165		return textUndetermined
166	}
167	
168	// traceText is the Address cell of the trace row.
169	func (c pathContainer) traceText() string {
170		if c.Attach == attachHost {
171			return textTraceSharedHost
172		}
173		return textTraceFromHost
174	}
175	
176	// dimNetwork reports whether the network row says nothing about a path.
177	func (c pathContainer) dimNetwork() bool {
178		return c.Attach == attachUndetermined || c.Attach == attachNone
179	}
