1	package netdiag
2	
3	import (
4		"context"
5		"log"
6		"net/netip"
7		"time"
8	
9		"github.com/anthnel/devdesk/internal/docker"
10		"github.com/anthnel/devdesk/internal/netiface"
11	)
12	
13	// bridgeState says what is known about the host interface of a container's
14	// network. The zero value means the read was not attempted.
15	type bridgeState int
16	
17	const (
18		bridgeNotRead    bridgeState = iota // nothing to read for this container
19		bridgeFound                         // this machine has the interface and it carries the gateway
20		bridgeAbsent                        // this machine has no interface of that name
21		bridgeUnverified                    // the answer cannot be given with certainty
22	)
23	
24	// pathBridge is the outcome of reading the container network's bridge. Name is
25	// set only when State is bridgeFound, and is display-safe.
26	type pathBridge struct {
27		State bridgeState
28		Name  string
29	}
30	
31	// readPathBridge reads the host interface that carries the gateway of the
32	// container's default-route network: the engine gives the interface name, this
33	// machine's interfaces say whether it exists. A failed read is logged, never
34	// shown (unless the run was canceled), and reported as bridgeUnverified.
35	func readPathBridge(ctx context.Context, n docker.ContainerNetworking, timeout time.Duration, e pathEngine) pathBridge {
36		if !n.Running {
37			return pathBridge{}
38		}
39		ep, ok := routeEndpoint(n)
40		if !ok {
41			return pathBridge{}
42		}
43		if ep.NetworkID == "" {
44			return pathBridge{State: bridgeUnverified}
45		}
46		nctx, cancel := context.WithTimeout(ctx, timeout)
47		defer cancel()
48		nb, err := e.network(nctx, ep.NetworkID)
49		if err != nil {
50			logBridgeError(ctx, "network", err)
51			return pathBridge{State: bridgeUnverified}
52		}
53		if nb.Name == "" {
54			return pathBridge{State: bridgeUnverified}
55		}
56		ifaces, err := e.interfaces(nctx)
57		if err != nil {
58			logBridgeError(ctx, "interfaces", err)
59			return pathBridge{State: bridgeUnverified}
60		}
61		b := classifyBridge(nb.Name, ep.Gateway, ifaces)
62		if b.State == bridgeFound {
63			if b.Name = engineText(b.Name); b.Name == "" {
64				return pathBridge{State: bridgeUnverified}
65			}
66		}
67		return b
68	}
69	
70	// logBridgeError logs a read failure unless the run was canceled.
71	func logBridgeError(ctx context.Context, what string, err error) {
72		if ctx.Err() == nil {
73			log.Printf("ERROR [netdiag/path] bridge %s: %v", what, err)
74		}
75	}
76	
77	// hostBridge returns the name of this machine's interface called exactly want
78	// (case sensitive) that carries gw among its IPv4 addresses, or "" when there
79	// is none. Malformed CIDR entries are ignored.
80	func hostBridge(want string, gw netip.Addr, ifaces []netiface.Interface) string {
81		if want == "" || !gw.IsValid() {
82			return ""
83		}
84		for _, ifc := range ifaces {
85			if ifc.Name != want {
86				continue
87			}
88			for _, cidr := range ifc.IPv4 {
89				if p, err := netip.ParsePrefix(cidr); err == nil && p.Addr() == gw {
90					return ifc.Name
91				}
92			}
93		}
94		return ""
95	}
96	
97	// classifyBridge answers three ways: bridgeFound when the interface called
98	// exactly want carries gw, bridgeAbsent when no interface has that name, and
99	// bridgeUnverified otherwise (including an empty want or an invalid gw).
100	func classifyBridge(want string, gw netip.Addr, ifaces []netiface.Interface) pathBridge {
101		if want == "" || !gw.IsValid() {
102			return pathBridge{State: bridgeUnverified}
103		}
104		if name := hostBridge(want, gw, ifaces); name != "" {
105			return pathBridge{State: bridgeFound, Name: name}
106		}
107		for _, ifc := range ifaces {
108			if ifc.Name == want {
109				return pathBridge{State: bridgeUnverified}
110			}
111		}
112		return pathBridge{State: bridgeAbsent}
113	}
