package netdiag

import (
	"fmt"

	"charm.land/lipgloss/v2"

	"github.com/anthnel/devdesk/internal/nettrace"
	"github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/datatable"
	"github.com/anthnel/devdesk/internal/ui/shortcut"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// pathBarLabel prefixes the target field in the bar.
const pathBarLabel = "Target › "

// pathColumns describes the Path column. Plain text in Cell, colour in Style
// (Rule 122). A silent hop is dim, never red: it is not a failure.
func pathColumns() []datatable.Column[pathStep] {
	hop := datatable.Column[pathStep]{
		Title: "Hop", Sizing: datatable.SizingFixed, MinWidth: 3,
		Cell: pathStep.hopCell,
	}
	step := datatable.Column[pathStep]{
		Title: "Step", Sizing: datatable.SizingFixed, MinWidth: 11,
		Cell:  pathStep.stepCell,
		Style: pathStepStyle,
	}
	address := datatable.Column[pathStep]{
		Title: "Address", Sizing: datatable.SizingContent, MinWidth: 15, Flex: 1,
		Cell:  pathStep.addressCell,
		Style: pathAddressStyle,
	}
	rtt := datatable.Column[pathStep]{
		Title: "RTT", Sizing: datatable.SizingFixed, MinWidth: 9,
		Cell:  pathStep.rttCell,
		Style: pathRTTStyle,
	}
	return []datatable.Column[pathStep]{hop, step, address, rtt}
}

func pathStepStyle(s pathStep) lipgloss.Style {
	if s.Kind != stepHop {
		return lipgloss.Style{}
	}
	switch s.Hop.Kind {
	case nettrace.HopSilent, nettrace.HopUnresolved:
		return theme.DimStyle
	case nettrace.HopError:
		return theme.SeverityTextStyle("MEDIUM")
	}
	return lipgloss.Style{}
}

func pathAddressStyle(s pathStep) lipgloss.Style {
	switch s.Kind {
	case stepTrace:
		return theme.DimStyle
	case stepNetwork:
		if s.Container.dimNetwork() {
			return theme.DimStyle
		}
	case stepHop:
		if !s.Hop.Addr.IsValid() {
			return theme.DimStyle
		}
	case stepInterface, stepGateway:
		if c := s.addressCell(); c == routeUndetermined || c == gatewayDirect {
			return theme.DimStyle
		}
	}
	return lipgloss.Style{}
}

func pathRTTStyle(s pathStep) lipgloss.Style {
	if s.Kind == stepHop && s.Hop.RTT <= 0 {
		return theme.DimStyle
	}
	return lipgloss.Style{}
}

// view renders the table; the body is never replaced (Rule 139). The open
// selector is drawn over it.
func (pm *PathModel) view() string {
	if pm.pickerOpen() {
		return pm.viewWithPicker(pm.table.View())
	}
	return pm.table.View()
}

// barView is the target field in its frame, two lines in every state.
func (pm *PathModel) barView(width int) string {
	return components.BarFrame(width, theme.KeyStyle.Render(pathBarLabel)+pm.input.View())
}

// statusLine is derived on every frame (Rule 128).
func (pm *PathModel) statusLine() components.Status {
	if pm.errText != "" {
		return components.Status{Text: pm.errText, Level: components.LevelError}
	}
	if pm.pickerOpen() {
		return pm.pickerStatus()
	}
	if pm.state != pathRunning {
		return components.Status{}
	}
	host := pm.target.Host
	n := pm.hopCount()
	if !pm.addr.IsValid() && n == 0 {
		return components.Status{Text: "Resolving " + host + "...", Activity: true}
	}
	where := host
	if pm.addr.IsValid() && pm.addr.String() != host {
		where += " (" + pm.addr.String() + ")"
	}
	noun := "hops"
	if n == 1 {
		noun = "hop"
	}
	return components.Status{
		Text:     fmt.Sprintf("Tracing %s — %d %s answered", where, n, noun),
		Activity: true,
	}
}

// headerInfo lists the target and, once a run ended, how it ended.
func (pm *PathModel) headerInfo() []shortcut.HeaderInfo {
	var out []shortcut.HeaderInfo
	if !pm.source.isHost() {
		out = append(out, shortcut.HeaderInfo{Key: "Source", Value: pm.source.Name, Style: theme.HeaderValueStyle})
	}
	if pm.target.Host != "" {
		value := pm.target.String()
		if pm.addr.IsValid() && pm.addr.String() != pm.target.Host {
			value += " (" + pm.addr.String() + ")"
		}
		out = append(out, shortcut.HeaderInfo{Key: "Target", Value: value, Style: theme.HeaderValueStyle})
	}
	if pm.result != nil {
		out = append(out, shortcut.HeaderInfo{Key: "Path", Value: pathOutcomeLabel(*pm.result), Style: theme.HeaderValueStyle})
	}
	return out
}

// shortcuts: the running mode replaces the list, the other states grey out
// (Rule 130).
func (pm *PathModel) shortcuts() shortcut.Shortcuts {
	if pm.pickerOpen() { // a mode: the list is replaced
		return shortcut.Shortcuts{
			{Key: "enter", Description: "Trace from it"},
			{Key: "esc", Description: "Close"},
		}
	}
	off := !pm.launchable().Enabled()
	source := shortcut.Shortcut{Key: pathSourceKey, Description: "Trace from…", Disabled: !pm.sourceChoosable().Enabled()}
	switch pm.state {
	case pathRunning:
		return shortcut.Shortcuts{{Key: "esc", Description: "Cancel the trace"}}
	case pathDone:
		return shortcut.Shortcuts{
			{Key: "tab", Description: "Switch tab"},
			{Key: "enter", Description: "Trace again", Disabled: off},
			source,
			{Key: "esc", Description: "Edit the target"},
			{Key: "?", Description: "Help"},
		}
	}
	return shortcut.Shortcuts{
		{Key: "tab", Description: "Switch tab"},
		{Key: "enter", Description: "Trace the path", Disabled: off},
		source,
	}
}

package netdiag

import (
	"fmt"
	"net"
	"net/netip"
	"strconv"
	"time"

	"github.com/anthnel/devdesk/internal/netcheck"
	"github.com/anthnel/devdesk/internal/nettrace"
)

// pathStepKind says which kind of row a pathStep is.
type pathStepKind int

// The kinds of row, in the order the column shows them.
const (
	stepContainer pathStepKind = iota
	stepNetwork
	stepBridge
	stepSource
	stepInterface
	stepGateway
	stepTrace
	stepHop
)

// pathRoute is the way out of this machine for the traced address.
type pathRoute struct {
	Known     bool // false: the lookup failed; interface and gateway are undetermined
	Interface string
	Source    netip.Addr // invalid: the stack did not say
	Gateway   netip.Addr // invalid: directly connected
}

// pathStep is one row of the Path column.
type pathStep struct {
	Kind      pathStepKind
	Container pathContainer // stepContainer, stepNetwork, stepBridge, stepTrace
	Route     pathRoute     // stepInterface, stepGateway
	Hop       nettrace.Hop  // stepHop
}

const (
	sourceLabel       = "this machine"
	routeUndetermined = "undetermined"
	gatewayDirect     = "directly connected"
)

// newPathRoute converts a route lookup into a pathRoute. A failed lookup
// discards whatever the hop holds. Addresses are unmapped to IPv4 when they can be.
func newPathRoute(hop netcheck.RouteHop, err error) pathRoute {
	if err != nil {
		return pathRoute{}
	}
	return pathRoute{
		Known:     true,
		Interface: hop.Interface,
		Source:    addrFromIP(hop.Source),
		Gateway:   addrFromIP(hop.Gateway),
	}
}

// addrFromIP returns ip as an unmapped netip.Addr, or the zero Addr for a nil or invalid ip.
func addrFromIP(ip net.IP) netip.Addr {
	addr, ok := netip.AddrFromSlice(ip)
	if !ok {
		return netip.Addr{}
	}
	return addr.Unmap()
}

// pathSteps returns the rows of the Path column: the source, then the
// interface and gateway when route is not nil, then the hops as selected by
// visiblePathHops. It returns nil while neither a route nor a hop exists.
// Neither input is modified.
func pathSteps(ctr *pathContainer, route *pathRoute, hops []nettrace.Hop) []pathStep {
	if ctr == nil && route == nil && len(hops) == 0 {
		return nil
	}
	var steps []pathStep
	if ctr != nil {
		steps = append(steps,
			pathStep{Kind: stepContainer, Container: *ctr},
			pathStep{Kind: stepNetwork, Container: *ctr},
		)
		if ctr.Bridge != "" {
			steps = append(steps, pathStep{Kind: stepBridge, Container: *ctr})
		}
	}
	steps = append(steps, pathStep{Kind: stepSource})
	if route != nil {
		steps = append(steps,
			pathStep{Kind: stepInterface, Route: *route},
			pathStep{Kind: stepGateway, Route: *route},
		)
	}
	if ctr != nil {
		steps = append(steps, pathStep{Kind: stepTrace, Container: *ctr})
	}
	for _, h := range visiblePathHops(hops) {
		steps = append(steps, pathStep{Kind: stepHop, Hop: h})
	}
	return steps
}

// hopCell is the TTL of a hop row; empty for the local rows.
func (s pathStep) hopCell() string {
	if s.Kind != stepHop {
		return ""
	}
	return strconv.Itoa(s.Hop.TTL)
}

// stepCell names the kind of row.
func (s pathStep) stepCell() string {
	switch s.Kind {
	case stepContainer:
		return "container"
	case stepNetwork:
		return "network"
	case stepBridge:
		return "bridge"
	case stepTrace:
		return "trace"
	case stepSource:
		return "source"
	case stepInterface:
		return "interface"
	case stepGateway:
		return "gateway"
	}
	return s.Hop.Kind.String()
}

// addressCell is the main text of the row.
func (s pathStep) addressCell() string {
	switch s.Kind {
	case stepContainer:
		return s.Container.containerText()
	case stepNetwork:
		return s.Container.networkText()
	case stepBridge:
		return s.Container.Bridge
	case stepTrace:
		return s.Container.traceText()
	case stepSource:
		return sourceLabel
	case stepInterface:
		return s.Route.interfaceText()
	case stepGateway:
		return s.Route.gatewayText()
	}
	return addrOrDash(s.Hop.Addr)
}

// rttCell is the round-trip time of a hop that answered; "-" otherwise.
func (s pathStep) rttCell() string {
	if s.Kind != stepHop {
		return ""
	}
	if s.Hop.RTT <= 0 {
		return "-"
	}
	return fmt.Sprintf("%.1f ms", float64(s.Hop.RTT)/float64(time.Millisecond))
}

// interfaceText is the interface name, followed by the source address when known.
func (r pathRoute) interfaceText() string {
	if !r.Known || (r.Interface == "" && !r.Source.IsValid()) {
		return routeUndetermined
	}
	name := r.Interface
	if name == "" {
		name = "unnamed"
	}
	if !r.Source.IsValid() {
		return name
	}
	return name + " (" + r.Source.String() + ")"
}

// gatewayText is the gateway address, or says the destination is directly connected.
func (r pathRoute) gatewayText() string {
	switch {
	case !r.Known:
		return routeUndetermined
	case !r.Gateway.IsValid() || r.Gateway.IsUnspecified():
		return gatewayDirect
	}
	return r.Gateway.String()
}

// addrOrDash formats an address, or "-" when there is none.
func addrOrDash(a netip.Addr) string {
	if !a.IsValid() {
		return "-"
	}
	return a.String()
}

